                 <small>${escapeHtml(product.note)}</small>
               </div>
               <span class="pill">${escapeHtml(product.badge)}</span>
             </div>
             <div class="card__actions">
               <button class="button" type="button" data-action="cart" data-name="${escapeHtml(product.name)}">
                 Add to bag
               </button>
               <button
                 class="button--secondary"
                 type="button"
                 data-action="save"
                 data-name="${escapeHtml(product.name)}"
                 aria-pressed="false"
               >
                 Save
               </button>
             </div>
           </div>
         </article>
       `;

       const ProductSection = ({ id, title, description, items, actionText }) => `
         <section class="section" id="${escapeHtml(id)}" aria-labelledby="${escapeHtml(id)}-heading">
           <div class="section__surface">
             <div class="section__header">
               <div>
                 <h2 id="${escapeHtml(id)}-heading">${escapeHtml(title)}</h2>
                 <p>${escapeHtml(description)}</p>
               </div>
               <a class="button--secondary" href="#maincontent">${escapeHtml(actionText)}</a>
             </div>
             <div class="grid grid--products">
               ${items.map(ProductCard).join("")}
             </div>
           </div>
         </section>
       `;

       const StoryCard = (story) => `
         <article class="story">
           <div class="story__visual" style="background:${escapeHtml(story.gradient)}" aria-hidden="true"></div>
           <div class="story__body">
             <span class="story__kicker">${escapeHtml(story.label)}</span>
             <h3 class="story__title">${escapeHtml(story.title)}</h3>
             <p class="story__summary">${escapeHtml(story.summary)}</p>
             <div class="story__meta">
               <span>${escapeHtml(story.readTime)}</span>
               <a class="button--ghost" href="#maincontent">${escapeHtml(story.cta)}</a>
             </div>
           </div>
         </article>
       `;

       const EditorialSection = () => `
         <section class="section" id="journal" aria-labelledby="journal-heading">
           <div class="section__surface">
             <div class="section__header">
               <div>
                 <h2 id="journal-heading">Editorial content</h2>
                 <p>Balance utility with inspiration through stories that connect product detail to daily routines.</p>
               </div>
               <a class="button--secondary" href="#maincontent">Visit the journal</a>
             </div>
             <div class="grid grid--stories">
               ${stories.map(StoryCard).join("")}
             </div>
           </div>
         </section>
       `;

       const Footer = () => `
         <footer class="footer" id="footer">
           <div class="footer__surface">
             <div class="footer__meta">
               <strong>Northstar Goods</strong>
               <span>Design-led essentials for work, home, and gifting.</span>
             </div>
             <nav class="footer__nav" aria-label="Footer">
               <a href="#maincontent">About</a>
               <a href="#maincontent">Shipping</a>
               <a href="#maincontent">Returns</a>
               <a href="#maincontent">Contact</a>
             </nav>
           </div>
         </footer>
       `;

       const App = () => `
         ${Header()}
         <main id="maincontent" tabindex="-1">
           ${Hero()}
           ${ProductSection({
             id: "featured",
             title: "Featured products",
             description: "The strongest mix of hero pieces, tactile finishes, and everyday upgrades.",
             items: featuredProducts,
             actionText: "Shop all featured",
           })}
           ${ProductSection({
             id: "deals",
             title: "Deals worth opening",
             description: "Time-sensitive markdowns on best sellers and practical upgrades across the catalog.",
             items: dealProducts,
             actionText: "See every deal",
           })}
           ${EditorialSection()}
         </main>
         ${Footer()}
       `;

       const app = document.getElementById("app");
       const statusMessage = document.getElementById("status-message");

       app.innerHTML = App();

       app.addEventListener("click", (event) => {
         const button = event.target.closest("button[data-action]");
         if (!button) {
           return;
         }

         const productName = button.dataset.name || "item";
         const action = button.dataset.action;

         if (action === "save") {
           const isPressed = button.getAttribute("aria-pressed") === "true";
           const nextPressed = String(!isPressed);
           button.setAttribute("aria-pressed", nextPressed);
           button.textContent = isPressed ? "Save" : "Saved";
           button.setAttribute("aria-label", `${isPressed ? "Save" : "Saved"} ${productName}`);
           statusMessage.textContent = isPressed ? `${productName} removed from saved items.` : `${productName} saved for later.`;
         }

         if (action === "cart") {
           statusMessage.textContent = `${productName} added to your bag.`;
         }
       });

       app.addEventListener("submit", (event) => {
         if (!event.target.matches(".search")) {
           return;
         }

         event.preventDefault();
         const query = event.target.querySelector("input").value.trim();
         statusMessage.textContent = query
           ? `Search requested for ${query}.`
           : "Enter a product category or keyword to search.";
       });
     </script>
   </body>
 </html>

')
